{
  "events": [
    {
      "source": "io.genesisdb.app",
      "subject": "/order/4",
      "type": "io.genesisdb.app.order-placed",
      "data": {
        "customer": "{{customerId}}",
        "amount": 75,
        "category": "c"
      }
    }
  ],
  "preconditions": [
    {
      "type": "isQueryResultTrue",
      "payload": {
        "query": "STREAM e FROM events WHERE e.type == 'io.genesisdb.app.order-placed' MAP COUNT() < 100"
      }
    }
  ]
}

{
  "query": "STREAM e FROM events WHERE e.subject UNDER '/order' MAP { id: e.id, amount: e.data.amount, category: e.data.category }"
}

{
  "query": "STREAM e FROM events WHERE e.type == 'io.genesisdb.app.order-placed' AND e.data.amount >= 75 ORDER BY e.data.amount DESC MAP { subject: e.subject, amount: e.data.amount }"
}

{
  "query": "STREAM e FROM events WHERE e.type == 'io.genesisdb.app.order-placed' MAP COUNT()"
}

{
  "query": "STREAM e FROM events WHERE e.type == 'io.genesisdb.app.order-placed' MAP { total: SUM(e.data.amount), average: AVG(e.data.amount), orders: COUNT() }"
}

{
  "query": "STREAM e FROM events WHERE e.type == 'io.genesisdb.app.order-placed' GROUP BY e.data.category MAP { category: e.data.category, orders: COUNT(), total: SUM(e.data.amount) } HAVING COUNT() >= 1"
}

{
  "query": "STREAM e FROM events WHERE e.subject DESCENDANTS '/customer' AND e.type IN ('io.genesisdb.app.customer-added', 'io.genesisdb.app.address-changed') MAP { * }"
}

{
  "query": "STREAM e FROM events WHERE e.type == 'io.genesisdb.app.customer-added' MAP { name: e.data.firstName + ' ' + e.data.lastName, city: e.data.address.city }"
}

{
  "query": "STREAM e FROM events WHERE e.subject UNDER '/order' ORDER BY e.time DESC LIMIT 2 MAP { id: e.id, time: e.time }"
}

{
  "query": "STREAM o FROM (STREAM e FROM events WHERE e.type == 'io.genesisdb.app.order-placed' MAP { amount: e.data.amount, category: e.data.category }) WHERE o.data.category == 'a' MAP { amount: o.data.amount }"
}

{
  "query": "STREAM e FROM events WHERE e.data.email == 'nobody@example.com' MAP COUNT() == 0"
}

{
  "query": "FROM e IN events WHERE e.subject UNDER '/order' TOP 2 PROJECT INTO { id: e.id }"
}
